import UIKit
import WebKit
import Metal
import MetalKit
import QuartzCore

// MARK: - SameLayerContainerViewControllerDelegate

protocol SameLayerContainerViewControllerDelegate: AnyObject {
    func container(_ vc: SameLayerContainerViewController, didFinishLoadingWebView webView: WKWebView)
    func container(_ vc: SameLayerContainerViewController, webView: WKWebView, didFailWithError error: Error)
    func containerDidRequestInputFocus(_ vc: SameLayerContainerViewController, payload: InputFocusPayload)
    func containerDidRequestInputDismiss(_ vc: SameLayerContainerViewController)
    func container(_ vc: SameLayerContainerViewController, hapticRequested payload: HapticPayload)
}

// MARK: - SameLayerContainerViewController

/// Hosts WKWebView, the native overlay container, and MetalTextureRedirectView.
/// Drives the 120Hz ProMotion CADisplayLink that synchronizes layout payloads to native overlays.
final class SameLayerContainerViewController: UIViewController {

    // MARK: - Configuration

    struct Configuration {
        var bundleURL: URL
        var backgroundColor: UIColor
        var enableMetalRedirect: Bool
        var preferredFrameRate: Int

        static var `default`: Configuration {
            Configuration(
                bundleURL: Bundle.main.bundleURL,
                backgroundColor: UIColor(red: 0.035, green: 0.035, blue: 0.063, alpha: 1.0),
                enableMetalRedirect: true,
                preferredFrameRate: 120
            )
        }
    }

    // MARK: - Public Properties

    weak var containerDelegate: SameLayerContainerViewControllerDelegate?
    private(set) var webView: WKWebView?
    private(set) var overlayContainerView: UIView?
    private(set) var metalRedirectView: MetalTextureRedirectView?
    private(set) var mirrorOverlayManager: MirrorOverlayManager?

    let configuration: Configuration
    let layoutBridge: LayoutBridge
    let inputBridge: InputBridge
    let hapticBridge: HapticBridge

    // MARK: - Private Properties

    private var displayLink: CADisplayLink?
    private var isDisplayLinkRunning = false

    // MARK: - Init

    init(configuration: Configuration,
         layoutBridge: LayoutBridge,
         inputBridge: InputBridge,
         hapticBridge: HapticBridge) {
        self.configuration = configuration
        self.layoutBridge = layoutBridge
        self.inputBridge = inputBridge
        self.hapticBridge = hapticBridge
        super.init(nibName: nil, bundle: nil)
    }

    required init?(coder: NSCoder) {
        fatalError("init(coder:) not implemented")
    }

    // MARK: - Lifecycle

    override func viewDidLoad() {
        super.viewDidLoad()
        view.backgroundColor = configuration.backgroundColor
        buildViewHierarchy()
        startDisplayLink()
    }

    override func viewWillAppear(_ animated: Bool) {
        super.viewWillAppear(animated)
        resumeDisplayLink()
    }

    override func viewDidDisappear(_ animated: Bool) {
        super.viewDidDisappear(animated)
        pauseDisplayLink()
    }

    override func viewDidLayoutSubviews() {
        super.viewDidLayoutSubviews()
        webView?.frame = view.bounds
        overlayContainerView?.frame = view.bounds
        metalRedirectView?.frame = view.bounds
    }

    override var preferredStatusBarStyle: UIStatusBarStyle { .lightContent }

    override func traitCollectionDidChange(_ previousTraitCollection: UITraitCollection?) {
        super.traitCollectionDidChange(previousTraitCollection)
        mirrorOverlayManager?.updateForTraitCollection(traitCollection)
    }

    deinit {
        tearDownDisplayLink()
        tearDownWebView()
    }

    // MARK: - View Hierarchy

    private func buildViewHierarchy() {
        // 1. Metal redirect view (behind WebView — receives WebGL texture)
        if configuration.enableMetalRedirect {
            setupMetalRedirectView()
        }

        // 2. WebView (transparent, layout-only)
        setupWebView()

        // 3. Overlay container (above WebView — native UI mirrors)
        setupOverlayContainer()
    }

    private func setupMetalRedirectView() {
        // Only create if Metal is available on this device
        guard let webView = webView ?? buildWebViewIfNeeded() else { return }
        let metalView = MetalTextureRedirectView(frame: view.bounds, webView: webView)
        metalView.autoresizingMask = [.flexibleWidth, .flexibleHeight]
        metalView.isUserInteractionEnabled = false
        view.addSubview(metalView)
        self.metalRedirectView = metalView
    }

    private func setupWebView() {
        let wv = buildWebViewIfNeeded()
        wv?.autoresizingMask = [.flexibleWidth, .flexibleHeight]
        if let wv = wv {
            view.addSubview(wv)
        }
    }

    @discardableResult
    private func buildWebViewIfNeeded() -> WKWebView? {
        if let existing = webView { return existing }

        let config = WKWebViewConfiguration()
        let contentController = WKUserContentController()

        // Register bridge handlers through the WeakScriptMessageHandler proxy
        contentController.add(WeakScriptMessageHandler(delegate: layoutBridge), name: "layoutBridge")
        contentController.add(WeakScriptMessageHandler(delegate: inputBridge),  name: "inputBridge")
        contentController.add(WeakScriptMessageHandler(delegate: hapticBridge), name: "hapticBridge")

        config.userContentController = contentController

        // Custom URL scheme handlers
        let handler = URLSchemeHandler(bundleURL: configuration.bundleURL)
        config.setURLSchemeHandler(handler, forURLScheme: "local")
        config.setURLSchemeHandler(handler, forURLScheme: "app")

        // Preferences
        if #available(iOS 14.0, *) {
            config.defaultWebpagePreferences.allowsContentJavaScript = true
        }
        config.preferences.javaScriptCanOpenWindowsAutomatically = false
        config.allowsInlineMediaPlayback = true
        config.mediaTypesRequiringUserActionForPlayback = []

        if #available(iOS 15.0, *) {
            config.preferences.isTextInteractionEnabled = false
        }

        // Shared process pool for efficiency
        config.processPool = WKProcessPool()

        let wv = WKWebView(frame: view.bounds, configuration: config)
        wv.isOpaque = false
        wv.backgroundColor = .clear
        wv.scrollView.backgroundColor = .clear
        wv.scrollView.isOpaque = false
        wv.scrollView.bounces = false
        wv.scrollView.alwaysBounceVertical = false
        wv.scrollView.alwaysBounceHorizontal = false
        wv.scrollView.showsVerticalScrollIndicator = false
        wv.scrollView.showsHorizontalScrollIndicator = false
        wv.scrollView.contentInsetAdjustmentBehavior = .never
        wv.scrollView.decelerationRate = .normal

        if #available(iOS 16.4, *) {
            wv.isInspectable = true
        }

        wv.navigationDelegate = self
        wv.uiDelegate = self

        self.webView = wv
        return wv
    }

    private func setupOverlayContainer() {
        let container = UIView(frame: view.bounds)
        container.autoresizingMask = [.flexibleWidth, .flexibleHeight]
        container.backgroundColor = .clear
        container.isOpaque = false
        container.isUserInteractionEnabled = false
        view.addSubview(container)
        self.overlayContainerView = container

        let manager = MirrorOverlayManager(containerView: container)
        self.mirrorOverlayManager = manager
    }

    // MARK: - Content Loading

    func loadContent() {
        guard let wv = webView else { return }

        // Primary: loadFileURL — gives full filesystem access from the bundle root
        if let indexURL = Bundle.main.url(forResource: "index", withExtension: "html") {
            wv.loadFileURL(indexURL, allowingReadAccessTo: Bundle.main.bundleURL)
            return
        }

        // Secondary: custom scheme
        if let localURL = URL(string: "local:///index.html") {
            wv.load(URLRequest(url: localURL))
            return
        }

        // Tertiary: data URL (SPA navigation history compatible)
        loadViaDataURL(webView: wv)
    }

    private func loadViaDataURL(webView: WKWebView) {
        DispatchQueue.global(qos: .userInitiated).async {
            guard let bundleURL = Bundle.main.url(forResource: "index", withExtension: "html"),
                  let data = try? Data(contentsOf: bundleURL) else {
                DispatchQueue.main.async {
                    let html = """
                    <html><body style='background:#050510;color:#fff;font-family:system-ui;
                    display:flex;align-items:center;justify-content:center;height:100vh;margin:0'>
                    <p>index.html not found in bundle.</p></body></html>
                    """
                    webView.loadHTMLString(html, baseURL: nil)
                }
                return
            }
            let base64 = data.base64EncodedString()
            let dataURLString = "data:text/html;base64,\(base64)"
            guard let dataURL = URL(string: dataURLString) else { return }
            DispatchQueue.main.async {
                webView.load(URLRequest(url: dataURL))
            }
        }
    }

    // MARK: - CADisplayLink

    private func startDisplayLink() {
        guard displayLink == nil else { return }
        let link = CADisplayLink(target: self, selector: #selector(displayLinkTick(_:)))
        link.preferredFramesPerSecond = 0 // use system maximum
        if #available(iOS 15.0, *) {
            link.preferredFrameRateRange = CAFrameRateRange(
                minimum: Float(min(60, configuration.preferredFrameRate)),
                maximum: Float(configuration.preferredFrameRate),
                preferred: Float(configuration.preferredFrameRate)
            )
        }
        link.add(to: .main, forMode: .common)
        self.displayLink = link
        isDisplayLinkRunning = true
    }

    private func pauseDisplayLink() {
        displayLink?.isPaused = true
        isDisplayLinkRunning = false
    }

    private func resumeDisplayLink() {
        displayLink?.isPaused = false
        isDisplayLinkRunning = true
    }

    private func tearDownDisplayLink() {
        displayLink?.invalidate()
        displayLink = nil
    }

    @objc private func displayLinkTick(_ link: CADisplayLink) {
        guard let payload = layoutBridge.consumePendingPayload() else { return }
        mirrorOverlayManager?.apply(elements: payload.elements)
    }

    // MARK: - WebView Teardown

    private func tearDownWebView() {
        webView?.stopLoading()
        webView?.configuration.userContentController.removeAllScriptMessageHandlers()
        webView = nil
    }

    // MARK: - Native Bridge Detection

    private func injectNativeBridgeDetectionScript() {
        let js = """
        (function(){
            if (window.__nativeAppDetected) return;
            window.__nativeAppDetected = true;
            window.__nativeApp = true;
            document.documentElement.setAttribute('data-native-app', 'true');
            if (window.scheduleBridgeFlush) window.scheduleBridgeFlush();
        })();
        """
        webView?.evaluateJavaScript(js, completionHandler: { _, error in
            if let error = error {
                print("[SameLayerContainerViewController] Native bridge injection error: \(error)")
            }
        })
    }
}

// MARK: - WKNavigationDelegate

extension SameLayerContainerViewController: WKNavigationDelegate {

    func webView(_ webView: WKWebView, didFinish navigation: WKNavigation!) {
        injectNativeBridgeDetectionScript()
        metalRedirectView?.updateSourceWebView(webView)
        containerDelegate?.container(self, didFinishLoadingWebView: webView)
    }

    func webView(_ webView: WKWebView, didFail navigation: WKNavigation!, withError error: Error) {
        let nsError = error as NSError
        // Ignore cancelled loads (e.g. during SPA navigation)
        guard nsError.code != NSURLErrorCancelled else { return }
        print("[SameLayerContainerViewController] Navigation failed: \(error)")
        containerDelegate?.container(self, webView: webView, didFailWithError: error)
    }

    func webView(_ webView: WKWebView, didFailProvisionalNavigation navigation: WKNavigation!, withError error: Error) {
        let nsError = error as NSError
        guard nsError.code != NSURLErrorCancelled else { return }
        print("[SameLayerContainerViewController] Provisional navigation failed: \(error)")
        containerDelegate?.container(self, webView: webView, didFailWithError: error)
    }

    func webView(
        _ webView: WKWebView,
        decidePolicyFor navigationAction: WKNavigationAction,
        decisionHandler: @escaping (WKNavigationActionPolicy) -> Void
    ) {
        guard let url = navigationAction.request.url else {
            decisionHandler(.allow)
            return
        }

        let scheme = url.scheme?.lowercased() ?? ""

        switch scheme {
        case "local", "app", "about", "file", "blob", "data":
            decisionHandler(.allow)
        case "http", "https":
            if navigationAction.navigationType == .linkActivated {
                UIApplication.shared.open(url, options: [:], completionHandler: nil)
                decisionHandler(.cancel)
            } else {
                decisionHandler(.allow)
            }
        default:
            if UIApplication.shared.canOpenURL(url) {
                UIApplication.shared.open(url, options: [:], completionHandler: nil)
            }
            decisionHandler(.cancel)
        }
    }
}

// MARK: - WKUIDelegate

extension SameLayerContainerViewController: WKUIDelegate {

    func webView(
        _ webView: WKWebView,
        runJavaScriptAlertPanelWithMessage message: String,
        initiatedByFrame frame: WKFrameInfo,
        completionHandler: @escaping () -> Void
    ) {
        let alert = UIAlertController(title: nil, message: message, preferredStyle: .alert)
        alert.addAction(UIAlertAction(title: "OK", style: .default) { _ in completionHandler() })
        present(alert, animated: true)
    }

    func webView(
        _ webView: WKWebView,
        runJavaScriptConfirmPanelWithMessage message: String,
        initiatedByFrame frame: WKFrameInfo,
        completionHandler: @escaping (Bool) -> Void
    ) {
        let alert = UIAlertController(title: nil, message: message, preferredStyle: .alert)
        alert.addAction(UIAlertAction(title: "Mégse", style: .cancel) { _ in completionHandler(false) })
        alert.addAction(UIAlertAction(title: "OK", style: .default) { _ in completionHandler(true) })
        present(alert, animated: true)
    }

    func webView(
        _ webView: WKWebView,
        runJavaScriptTextInputPanelWithPrompt prompt: String,
        defaultText: String?,
        initiatedByFrame frame: WKFrameInfo,
        completionHandler: @escaping (String?) -> Void
    ) {
        let alert = UIAlertController(title: prompt, message: nil, preferredStyle: .alert)
        alert.addTextField { tf in tf.text = defaultText }
        alert.addAction(UIAlertAction(title: "Mégse", style: .cancel) { _ in completionHandler(nil) })
        alert.addAction(UIAlertAction(title: "OK", style: .default) { _ in
            completionHandler(alert.textFields?.first?.text)
        })
        present(alert, animated: true)
    }
}

