        configure(displayLink: displayLink)
        displayLink.add(to: .main, forMode: .common)
        self.displayLink = displayLink
    }

    private func configure(displayLink: CADisplayLink) {
        let requestedRate = max(1, configuration.preferredFrameRate)

        if #available(iOS 15.0, *) {
            let maximumRate = Float(requestedRate)
            let minimumRate = min(60.0, maximumRate)

            displayLink.preferredFrameRateRange = CAFrameRateRange(
                minimum: minimumRate,
                maximum: maximumRate,
                preferred: maximumRate
            )
        } else {
            displayLink.preferredFramesPerSecond = requestedRate
        }
    }

    private func pauseDisplayLink() {
        displayLink?.isPaused = true
    }

    private func resumeDisplayLink() {
        displayLink?.isPaused = false
    }

