        webView?.uiDelegate = nil
        webView?.configuration.userContentController.removeScriptMessageHandler(forName: "layoutBridge")
        webView?.configuration.userContentController.removeScriptMessageHandler(forName: "inputBridge")
        webView?.configuration.userContentController.removeScriptMessageHandler(forName: "hapticBridge")
