        metalRedirectView?.removeFromSuperview()
        overlayContainerView?.removeFromSuperview()

        webView = nil
        metalRedirectView = nil
        overlayContainerView = nil
        mirrorOverlayManager = nil
    }

    private func openExternally(_ url: URL) {
        guard UIApplication.shared.canOpenURL(url) else {
            return
        }

        UIApplication.shared.open(url, options: [:], completionHandler: nil)
    }

    private func presentJavaScriptAlert(
        title: String?,
        message: String?,
        textFieldConfiguration: ((UITextField) -> Void)? = nil,
        actions: [(String, UIAlertAction.Style, (UIAlertController) -> Void)]
    ) {
        guard presentedJavaScriptAlert == nil,
              viewIfLoaded?.window != nil,
              presentedViewController == nil else {
            return
        }

        let alert = UIAlertController(title: title, message: message, preferredStyle: .alert)

        if let textFieldConfiguration {
            alert.addTextField(configurationHandler: textFieldConfiguration)
        }

        for (title, style, handler) in actions {
            alert.addAction(UIAlertAction(title: title, style: style) { [weak alert] _ in
                guard let alert else {
                    return
                }

                handler(alert)
            })
        }

        presentedJavaScriptAlert = alert

        present(alert, animated: true) { [weak self, weak alert] in
            guard let self, let alert else {
                return
            }

            if self.presentedJavaScriptAlert !== alert {
                return
            }
        }
    }
