// Serves bundle assets over the custom local:// and app:// URL schemes.
// Handles chunked reads, MIME resolution, cancellation, and all error paths.

final class URLSchemeHandler: NSObject, WKURLSchemeHandler {

    // MARK: - State

    private let bundleURL: URL
    private let queue = DispatchQueue(label: "com.app.urlschemehandler", qos: .userInitiated, attributes: .concurrent)
    private var activeTasks: [ObjectIdentifier: WKURLSchemeTask] = [:]
    private var cancelledTaskIDs: Set<ObjectIdentifier> = []
    private let taskLock = NSLock()

    // MARK: - Constants

    private static let chunkSize: Int = 65_536  // 64 KiB

    // MARK: - Init

    init(bundleURL: URL) {
        self.bundleURL = bundleURL
        super.init()
    }

    // MARK: - WKURLSchemeHandler

    func webView(_ webView: WKWebView, start urlSchemeTask: WKURLSchemeTask) {
        let taskID = ObjectIdentifier(urlSchemeTask)
        taskLock.lock()
        activeTasks[taskID] = urlSchemeTask
        taskLock.unlock()

        queue.async { [weak self] in
            guard let self = self else { return }
            self.serve(task: urlSchemeTask, taskID: taskID)
        }
    }

    func webView(_ webView: WKWebView, stop urlSchemeTask: WKURLSchemeTask) {
        let taskID = ObjectIdentifier(urlSchemeTask)
        taskLock.lock()
        activeTasks.removeValue(forKey: taskID)
        cancelledTaskIDs.insert(taskID)
        taskLock.unlock()
    }

    // MARK: - Private Serving Logic

    private func serve(task: WKURLSchemeTask, taskID: ObjectIdentifier) {
        guard !isCancelled(taskID) else { return }

