        let taskID = ObjectIdentifier(urlSchemeTask)

        taskLock.lock()
        taskRecords[taskID] = TaskRecord(task: urlSchemeTask)
        taskLock.unlock()

        queue.async { [weak self, weak urlSchemeTask] in
            guard let self, let urlSchemeTask else {
                return
            }

            self.serve(task: urlSchemeTask, taskID: taskID)
        }
    }

    func webView(_ webView: WKWebView, stop urlSchemeTask: WKURLSchemeTask) {
        let taskID = ObjectIdentifier(urlSchemeTask)

        taskLock.lock()

        if let record = taskRecords[taskID],
           record.task === urlSchemeTask {
