import UIKit

final class ViewController: UIViewController {

    private let coordinator = ApplicationCoordinator()

    override func viewDidLoad() {
        super.viewDidLoad()

        view.backgroundColor = UIColor(
            red: 0.035,
            green: 0.035,
            blue: 0.063,
